import{_ as c,r as t,o as l,c as i,e,a as n,d as a,s as u}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Behaviors - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Comparison to Traits","slug":"comparison-to-traits","link":"#comparison-to-traits","children":[]},{"level":2,"title":"Extending Constructors","slug":"extending-constructors","link":"#extending-constructors","children":[{"level":4,"title":"Dynamically Declaring Properties","slug":"dynamically-declaring-properties","link":"#dynamically-declaring-properties","children":[]},{"level":4,"title":"Retrieving Dynamic Properties","slug":"retrieving-dynamic-properties","link":"#retrieving-dynamic-properties","children":[]},{"level":4,"title":"Dynamically Creating Methods","slug":"dynamically-creating-methods","link":"#dynamically-creating-methods","children":[]},{"level":4,"title":"Checking the Existence of a Method","slug":"checking-the-existence-of-a-method","link":"#checking-the-existence-of-a-method","children":[]},{"level":4,"title":"List All Available Methods","slug":"list-all-available-methods","link":"#list-all-available-methods","children":[]},{"level":4,"title":"Dynamically Implementing a Behavior","slug":"dynamically-implementing-a-behavior","link":"#dynamically-implementing-a-behavior","children":[]}]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[{"level":4,"title":"Behavior / Extension class","slug":"behavior-extension-class","link":"#behavior-extension-class","children":[]},{"level":4,"title":"Extending a Class","slug":"extending-a-class","link":"#extending-a-class","children":[]},{"level":4,"title":"Using the Extension","slug":"using-the-extension","link":"#using-the-extension","children":[]},{"level":4,"title":"Detecting Utilized Extensions","slug":"detecting-utilized-extensions","link":"#detecting-utilized-extensions","children":[]},{"level":3,"title":"Soft Definition","slug":"soft-definition","link":"#soft-definition","children":[]},{"level":3,"title":"Using Traits Instead of Base Classes","slug":"using-traits-instead-of-base-classes","link":"#using-traits-instead-of-base-classes","children":[]}]}],"relativePath":"2.x/services/behaviors.md","filePath":"2.x/services/behaviors.md"}'),r={name:"2.x/services/behaviors.md"};function k(d,s,h,m,g,y){const p=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[e(p),s[0]||(s[0]=n("h1",null,"Behaviors",-1)),e(o),s[1]||(s[1]=n("p",null,[a("Behaviors add the ability for classes to have "),n("em",null,"private traits"),a(", also known as Behaviors. These are similar to "),n("a",{href:"http://php.net/manual/en/language.oop5.traits.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("native PHP Traits"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(" except they have some distinct benefits:")],-1)),s[2]||(s[2]=u(`<ol><li>Behaviors have their own constructor.</li><li>Behaviors can have private or protected methods.</li><li>Methods and property names can conflict safely.</li><li>Classes can be extended with behaviors dynamically.</li></ol><h2 id="comparison-to-traits"><a href="#comparison-to-traits" class="header-anchor">#</a> Comparison to Traits</h2><p>Where you might use a PHP trait like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A behavior is used in a similar fashion:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Where you might define a trait like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">trait</span> <span class="token class-name-definition class-name">UtilityFunctions</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A behavior is defined like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UtilityFunctions</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$parent</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span> <span class="token operator">=</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The extended object is always passed as the first parameter to the Behavior&#39;s constructor.</p><p>To summarize:</p><ul><li>Extend \\October\\Rain\\Extension\\ExtensionBase to declare your class as a Behaviour</li><li>The class wanting to implement the Behaviour needs to extend \\October\\Rain\\Extension\\Extendable</li></ul><blockquote><p><strong>Note</strong>: See <a href="#oc-using-traits-instead-of-base-classes">Using Traits Instead of Base Classes</a></p></blockquote><h2 id="extending-constructors"><a href="#extending-constructors" class="header-anchor">#</a> Extending Constructors</h2><p>Any class that uses the <code>Extendable</code> or <code>ExtendableTrait</code> can have its constructor extended with the static <code>extend</code> method. The argument should pass a closure that will be called as part of the class constructor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">MyNamespace<span class="token punctuation">\\</span>Controller</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="dynamically-declaring-properties"><a href="#dynamically-declaring-properties" class="header-anchor">#</a> Dynamically Declaring Properties</h4><p>Properties can be declared on an extendable object by calling <code>addDynamicProperty</code> and passing a property name and value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicProperty</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;tagsCache&#39;</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: Attempting to set undeclared properties directly on the object that implements the <strong>October\\Rain\\Extension\\ExtendableTrait</strong> will throw an expection.</p></blockquote><h4 id="retrieving-dynamic-properties"><a href="#retrieving-dynamic-properties" class="header-anchor">#</a> Retrieving Dynamic Properties</h4><p>Properties created dynamically can be retrieved with the getDynamicProperties function inherited from the ExtendableTrait.</p><p>So retrieving all dynamic properties would look like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">getDynamicProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This will return an associative array [key =&gt; value], with the key being the dynamic property name and the value being the property value.</p><p>If we know what property we want we can simply append the key (property name) to the function:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">getDynamicProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token variable">$key</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="dynamically-creating-methods"><a href="#dynamically-creating-methods" class="header-anchor">#</a> Dynamically Creating Methods</h4><p>Methods can be created to an extendable object by calling <code>addDynamicMethod</code> and passing a method name and callable object, like a <code>Closure</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicProperty</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;tagsCache&#39;</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">tagsCache</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">tagsCache</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">tagsCache</span> <span class="token operator">=</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">tags</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="checking-the-existence-of-a-method"><a href="#checking-the-existence-of-a-method" class="header-anchor">#</a> Checking the Existence of a Method</h4><p>You can check for the existence of a method in an <code>Extendable</code> class by using the <code>methodExists</code> method - similar to the PHP <code>method_exists()</code> function. This will detect both standard methods and dynamic methods that have been added through a <code>addDynamicMethod</code> call. <code>methodExists</code> accepts one parameter: a string of the method name to check the existence of.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">tagsCache</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;missingMethod&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span>
</code></pre></div><h4 id="list-all-available-methods"><a href="#list-all-available-methods" class="header-anchor">#</a> List All Available Methods</h4><p>To retrieve a list of all available methods in an <code>Extendable</code> class, you can use the <code>getClassMethods</code> method. This method operates similar to the PHP <code>get_class_methods()</code> function in that it returns an array of available methods in a class, but in addition to defined methods in the class, it will also list any methods provided by an extension or through an <code>addDynamicMethod</code> call.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">tagsCache</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>

<span class="token variable">$methods</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">getClassMethods</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">/**
 * $methods = [
 *   0 =&gt; &#39;__construct&#39;,
 *   1 =&gt; &#39;extend&#39;,
 *   2 =&gt; &#39;getTagsAttribute&#39;,
 *   ...
 * ];
 */</span>
</code></pre></div><h4 id="dynamically-implementing-a-behavior"><a href="#dynamically-implementing-a-behavior" class="header-anchor">#</a> Dynamically Implementing a Behavior</h4><p>This unique ability to extend constructors allows behaviors to be implemented dynamically, for example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * Extend the RainLab.Users controller to include the RelationController behavior too
 */</span>
<span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Users</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

    <span class="token comment">// Implement the list controller behavior dynamically</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">implementClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Declare the relationConfig property dynamically for the RelationController behavior to use</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">addDynamicProperty</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relationConfig&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;$/myvendor/myplugin/controllers/users/config_relation.yaml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To avoid conflicts with other plugins doing the same thing, it is advisable the merge the configuration using the approach below.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">UsersController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

    <span class="token comment">// Implement the list controller behavior dynamically</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">implementClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Define property if not already defined</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">addDynamicProperty</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relationConfig&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Splice in configuration safely</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token property">relationConfig</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">mergeConfig</span><span class="token punctuation">(</span>
        <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token property">relationConfig</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;$/myvendor/myplugin/controllers/users/config_relation.yaml&#39;</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><h4 id="behavior-extension-class"><a href="#behavior-extension-class" class="header-anchor">#</a> Behavior / Extension class</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">MyNamespace<span class="token punctuation">\\</span>Behaviors</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FormController</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var Reference to the extended object.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * Constructor
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the FormController Behavior!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;You might not see me...&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><h4 id="extending-a-class"><a href="#extending-a-class" class="header-anchor">#</a> Extending a Class</h4><p>This <code>Controller</code> class will implement the <code>FormController</code> behavior and then the methods will become available (mixed in) to the class. We will override the <code>otherMethod</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">MyNamespace</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Controller</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>

    <span class="token comment">/**
     * Implement the FormController behavior
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>MyNamespace<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the main Controller!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><h4 id="using-the-extension"><a href="#using-the-extension" class="header-anchor">#</a> Using the Extension</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">MyNamespace<span class="token punctuation">\\</span>Controller</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the FormController Behavior!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the main Controller!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: You might not see me...</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="detecting-utilized-extensions"><a href="#detecting-utilized-extensions" class="header-anchor">#</a> Detecting Utilized Extensions</h4><p>To check if an object has been extended with a behavior, you may use the <code>isClassExtendedWith</code> method on the object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">isClassExtendedWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can extend a class dynamically with the <code>extendClassWith</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">extendClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>implementClassWith</code> method will safely check if the class is extended with the behavior and then implement it.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">implementClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="soft-definition"><a href="#soft-definition" class="header-anchor">#</a> Soft Definition</h3><p>If a behavior class does not exist, like a trait, a <em>Class not found</em> error will be thrown. In some cases you may wish to suppress this error, for conditional implementation if a behavior is present in the system. You can do this by placing an <code>@</code> symbol at the beginning of the class name.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;@&#39;</span><span class="token operator">.</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Translate<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>TranslatableModel</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If the class name <code>RainLab\\Translate\\Behaviors\\TranslatableModel</code> does not exist, no error will be thrown. This is the equivalent of the following code:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">class_exists</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Translate<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>TranslatableModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">implement</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Translate<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>TranslatableModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-using-traits-instead-of-base-classes"></a></p><h3 id="using-traits-instead-of-base-classes"><a href="#using-traits-instead-of-base-classes" class="header-anchor">#</a> Using Traits Instead of Base Classes</h3><p>Sometimes your class may already extend a parent class outside of your source control, making it so you are unable to extend the <code>ExtensionBase</code> or <code>Extendable</code> classes. Instead you can use these traits and your classes will have to be implemented as follows.</p><p>First let&#39;s create the class that will act as a Behaviour, ie. can be implemented by other classes.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">MyNamespace<span class="token punctuation">\\</span>Behaviors</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">WaveBehaviour</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionTrait</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * When using the Extensiontrait, your behaviour also has to implement this method
     * @see \\October\\Rain\\Extension\\ExtensionBase
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">extend</span><span class="token punctuation">(</span><span class="token keyword type-hint">callable</span> <span class="token variable">$callback</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">extensionExtendCallback</span><span class="token punctuation">(</span><span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">wave</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;*waves*&lt;br&gt;&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p>Now let&#39;s create the class that is able to implement behaviours using the ExtendableTrait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">AI</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtendableTrait</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var array Extensions implemented by this class.
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * Constructor
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendableConstruct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__get</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendableGet</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__set</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendableSet</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__call</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendableCall</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">__callStatic</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">extendableCallStatic</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">extend</span><span class="token punctuation">(</span><span class="token keyword type-hint">callable</span> <span class="token variable">$callback</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">extendableExtendCallback</span><span class="token punctuation">(</span><span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">youGotBrains</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;I&#39;ve got an AI!&lt;br&gt;&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The AI class is now able to use behaviours. Let&#39;s extend it and have this class implement the WaveBehaviour.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">MyNamespace<span class="token punctuation">\\</span>Classes</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Robot</span> <span class="token keyword">extends</span> <span class="token class-name">AI</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>MyNamespace<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>WaveBehaviour</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">identify</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;I&#39;m a Robot&lt;br&gt;&quot;</span><span class="token punctuation">;</span>
        <span class="token keyword">echo</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">youGotBrains</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">echo</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">wave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can now utilize the Robot as follows:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$robot</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Robot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$robot</span><span class="token operator">-&gt;</span><span class="token function">identify</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Which will output:</p><div class="language- extra-class"><pre class="language-text"><code>I&#39;m a Robot
I&#39;ve got an AI!
*waves*
</code></pre></div><p>Remember:</p><ul><li>When using the <code>ExtensionTrait</code> the methods from <code>ExtensionBase</code> should be applied to the class.</li><li>When using the <code>ExtendableTrait</code> the methods from <code>Extendable</code> should be applied to the class.</li></ul>`,77))])}const v=c(r,[["render",k]]);export{b as __pageData,v as default};
